/*
 * @ignore
 * @method
 * @name predictfun#stripPriceFormatting
 * @description drops the formatting the venue puts in a price but not in its slug - the currency sign, and a comma that sits between two digits
 * @param {string} [text] the raw title or outcome label
 * @returns {string} the same text with '$' removed and thousands separators closed up
 */
    pub fn strip_price_formatting(&self, text: Option<&str>) -> Option<String> {
        if (text.is_none()) {
            return None;
        }
        let digits: String = "0123456789".to_string();
        let chars: Vec<Value> = self.string_to_chars_array(Value::from(text)).as_array().cloned().unwrap_or_default();
        let mut stripped: String = "".to_string();
        let mut prevCh: Option<String> = Some("".to_string());
        // a comma after a digit waits for the next char: it is dropped only when that one is a digit too
        let mut pendingComma: bool = false;
        {
                        let mut i: i64 = 0;
            let mut __for_first_10: bool = true;
            while { if !__for_first_10 { i += 1; } __for_first_10 = false; i < (chars.len() as i64) } {
            let ch: Option<String> = chars.get(i as usize).and_then(Value::as_str).map(str::to_owned);
            let isDigit: bool = ((if let (Some(__h), Some(__n)) = (Some(digits.as_str()), ch.as_deref()) { if let Some(__i) = __h.find(__n) { __i as i64 } else { -1 } } else { -1 })) >= 0;
            if pendingComma && !isDigit {
                stripped = format!("{}{}", stripped, ",");
            }
            pendingComma = false;
            if (ch.as_deref() == Some(",")) {
                // only a comma between two digits is a thousands separator: "1,500" has to close
                // up to "1500" to match the venue's comma-free slug. a comma anywhere else is
                // ordinary punctuation and stays, so it still separates words
                if (i > 0) && (((if let (Some(__h), Some(__n)) = (Some(digits.as_str()), prevCh.as_deref()) { if let Some(__i) = __h.find(__n) { __i as i64 } else { -1 } } else { -1 })) >= 0) {
                    pendingComma = true;
                }  else {
                    stripped = format!("{}{}", stripped, ch.as_deref().unwrap_or("null"));
                }
            }  else if (ch.as_deref() != Some("$")) {
                stripped = format!("{}{}", stripped, ch.as_deref().unwrap_or("null"));
            }
            prevCh = ch;
        }
        }
        if pendingComma {
            stripped = format!("{}{}", stripped, ",");
        }
        return Some(stripped);
}

/*
 * @ignore
 * @method
 * @name predictfun#titleForMarketSymbol
 * @description decides what of a market title belongs in the unified symbol, given how many markets its topic holds
 * @param {string} [topicSlug] the slug of the enclosing topic
 * @param {string} [title] the market title
 * @param {int} [marketCount] how many markets the topic carries
 * @returns {string} the title to append, or the slug itself when the topic holds a single market
 */
    pub fn title_for_market_symbol(&self, topicSlug: Option<&str>, title: Option<&str>, optional_args: &[&Value]) -> Option<String> {
        let marketCount = get_arg(optional_args, 0, Value::Null);
        // a topic holding one market needs nothing to tell its markets apart, and the title there
        // only restates the slug in another spelling - the venue writes the same window as
        // btc-updown-5m-1789017900 and as "Bitcoin Up or Down - September 10, 1:25AM-1:30AM ET".
        // returning the slug makes slugToMarketSymbol collapse the two halves into one part.
        // inside a multi-market topic the title is what keeps the handles apart, so it stays
        if (marketCount.as_f64() == Some(1.0)) && (topicSlug.is_some()) {
            return topicSlug.map(str::to_owned);
        }
        return self.strip_price_formatting(title);
}

